#include <vector>
#include <algorithm>
#include <cmath>
extern "C" void solve(const double* C,int n,int* asg){
 std::vector<double> p(n,0.0); std::vector<int> own(n), q(n);
 double eps=.05;
 while(eps>1e-13){
  std::fill(own.begin(),own.end(),-1); std::fill(asg,asg+n,-1);
  int top=n; for(int i=0;i<n;i++)q[i]=i;
  while(top){
   int i=q[--top], bj=0; double best=-C[(long)i*n]-p[0], sec=-1e300;
   for(int j=1;j<n;j++){double v=-C[(long)i*n+j]-p[j]; if(v>best){sec=best;best=v;bj=j;}else if(v>sec)sec=v;}
   p[bj]+=best-sec+eps; int old=own[bj];own[bj]=i;asg[i]=bj;if(old>=0)q[top++]=old;
  }
  eps*=.1;
 }
}
